: #'BytecodeDescriptor *'>	<var: #mcpc type: #'char *'>	<var: #argArray type: #'void *'>	| annotation entryPoint tuple counter argArrayOop cogMethodSqInt localIntrospectionData localIntrospectionDataIndex localCounterIndex cogMethod |	"N.B. Counters are always 32-bits, having two 16-bit halves for the reached and taken counts."	<var: #counter type: #'unsigned int'>	argArrayOop := self cCoerceSimple: argArray to: #sqInt.	cogMethodSqInt := objectMemory fetchPointer: 0 ofObject: argArrayOop.	localIntrospectionData := objectMemory fetchPointer: 1 ofObject: argArrayOop.	localIntrospectionDataIndex := objectMemory fetchPointer: 2 ofObject: argArrayOop.	localCounterIndex := objectMemory fetchPointer: 3 ofObject: argArrayOop.		cogMethod := self cCoerceSimple: cogMethodSqInt to: #'CogMethod *'.	descriptor ifNil:[		^0	].	descriptor isBranch ifTrue:		["it's a branch; conditional?"		 (descriptor isBranchTrue or: [descriptor isBranchFalse]) ifTrue: [			counter := (self cCoerce: (cogMethod) to: #'unsigned int *') at: localCounterIndex.			tuple := self picDataForCounter: counter at: bcpc + 1.			tuple = 0 ifTrue: [^PrimErrNoMemory].			objectMemory storePointer: localIntrospectionDataIndex ofObject: localIntrospectionData withValue: tuple.			localIntrospectionDataIndex := localIntrospectionDataIndex + 1.			localCounterIndex := localCounterIndex + 1.			objectMemory storePointer: 2 ofObject: argArrayOop withValue: localIntrospectionDataIndex.			objectMemory storePointer: 3 ofObject: argArrayOop withValue: localCounterIndex.		].		 ^0].	annotation := isBackwardBranchAndAnnotation >> 1.	((self isPureSendAnnotation: annotation)	 and: [entryPoint := backEnd callTargetFromReturnAddress: mcpc asUnsignedInteger.		 entryPoint > methodZoneBase]) ifFalse: "send is not linked, or is not a send"		[^0].	self targetMethodAndSendTableFor: entryPoint "It's a linked send; find which kind."		annotation: annotation		into: [:targetMethod :sendTable| | methodClassIfSuper association |			methodClassIfSuper := nil.			sendTable = superSendTrampolines ifTrue:				[methodClassIfSuper := coInterpreter methodClassOf: cogMethod methodObject].			sendTable = directedSuperSendTrampolines ifTrue:				[association := backEnd literalBeforeInlineCacheTagAt: mcpc asUnsignedInteger.				 methodClassIfSuper := objectRepresentation valueOfAssociation: association].			tuple := self picDataForSendTo: targetMethod						methodClassIfSuper: methodClassIfSuper						at: mcpc						bcpc: bcpc + 1].	tuple = 0 ifTrue: [^PrimErrNoMemory].	objectMemory storePointer: localIntrospectionDataIndex ofObject: localIntrospectionData withValue: tuple.	localIntrospectionDataIndex := localIntrospectionDataIndex + 1.	objectMemory storePointer: 1 ofObject: argArrayOop withValue: localIntrospectionData.	objectMemory storePointer: 2 ofObject: argArrayOop withValue: localIntrospectionDataIndex.	^0! !!Cogit methodsFor: 'pic - helpers - private - print' stamp: 'NMS 10/14/2025 03:32'!picDataForBlockEntry: blockEntryMcpc args: argsOop	"Collect the branch and send data for the block method starting at blockEntryMcpc, storing it into picData."	<returnTypeC: #usqInt>	| cogBlockMethod argArray |	<var: #cogBlockMethod type: #'CogBlockMethod *'>	<var: #argArray type: #'void *'>	argArray := self cCoerceSimple: argsOop to: #'void *'.	cogBlockMethod := self cCoerceSimple: blockEntryMcpc - (self sizeof: CogBlockMethod) to: #'CogBlockMethod *'.	cogBlockMethod stackCheckOffset = 0 ifTrue:[		^0	].	^self		mapFor: cogBlockMethod		bcpc: cogBlockMethod startpc		performUntil: #picDataFor:Annotation:Mcpc:Bcpc:args:		arg: argArray! !!Cogit methodsFor: 'pic - helpers - private - print' stamp: 'NMS 10/14/2025 01:54'!picDataForCounter: counter at: bcpc	| tuple |	"N.B. Counters are always 32-bits, having two 16-bit halves for the reached and taken counts."	<var: #counter type: #'unsigned int'>	tuple := objectMemory				eeInstantiateClassIndex: ClassArrayCompactIndex				format: objectMemory arrayFormat				numSlots: 3.	tuple = 0 ifTrue:		[^0].	objectMemory		storePointerUnchecked: 0 ofObject: tuple withValue: (objectMemory integerObjectOf: bcpc).	^tuple! !!Cogit methodsFor: 'pic - helpers - private - print' stamp: 'NMS 10/14/2025 04:20'!picDataForSendTo: cogMethod methodClassIfSuper: methodClassOrNil at: sendMcpc bcpc: sendBcpc	"Answer a tuple with the send data for a linked send to cogMethod.	 If the target is a CogMethod (monomorphic send) answer		{ bytecode pc, inline cache class, target method }	 If the target is an open PIC (megamorphic send) answer		{ bytecode pc, nil, send selector }	If the target is a closed PIC (polymorphic send) answer		{ bytecode pc, first class, target method, second class, second target method, ... }"	<var: #cogMethod type: #'CogMethod *'>	<var: #sendMcpc type: #'char *'>	| tuple class |	tuple := objectMemory					eeInstantiateClassIndex: ClassArrayCompactIndex					format: objectMemory arrayFormat					numSlots: (cogMethod isCMClosedPIC								ifTrue: [2 * cogMethod cPICNumCases + 1]								ifFalse: [3]).	tuple = 0 ifTrue:		[^0].	objectMemory storePointerUnchecked: 0 ofObject: tuple withValue: (objectMemory integerObjectOf: sendBcpc).	cogMethod isCMMethodEtAl ifTrue:		[class := methodClassOrNil ifNil:					[objectRepresentation classForInlineCacheTag: (backEnd inlineCacheTagAt: sendMcpc asUnsignedInteger)].		 objectMemory			storePointer: 1 ofObject: tuple withValue: class;			storePointer: 2 ofObject: tuple withValue: cogMethod methodObject.		^tuple].	cogMethod isCMClosedPIC ifTrue:		[self populate: tuple withPICInfoFor: cogMethod firstCacheTag: (backEnd inlineCacheTagAt: sendMcpc asUnsignedInteger).		^tuple].	cogMethod isCMOpenPIC ifTrue:		[objectMemory			storePointerUnchecked: 1 ofObject: tuple withValue: objectMemory nilObject;			storePointer: 2 ofObject: tuple withValue: cogMethod selector.		^tuple].	self error: 'invalid method type'.	^0 "to get Slang to type this method as answering sqInt"! !!Cogit methodsFor: 'pic - helpers - private - print' stamp: 'NMS 10/14/2025 01:35'!populate: tuple withPICInfoFor: cPIC firstCacheTag: firstCacheTag	"Populate tuple (which must be large enough) with the ClosedPIC's target method class pairs.	 The first entry in tuple contains the bytecode pc for the send, so skip the tuple's first field."	<var: #cPIC type: #'CogMethod *'>	| pc cacheTag classOop entryPoint targetMethod value |	<var: #targetMethod type: #'CogMethod *'>	1 to: cPIC cPICNumCases do:		[:i|		pc := self addressOfEndOfCase: i inCPIC: cPIC.		cacheTag := i = 1						ifTrue: [firstCacheTag]						ifFalse: [backEnd literal32BeforeFollowingAddress: pc - backEnd jumpLongConditionalByteSize].		classOop := objectRepresentation classForInlineCacheTag: cacheTag.		objectMemory storePointer: i * 2 - 1 ofObject: tuple withValue: classOop.		entryPoint := i = 1						ifTrue: [backEnd jumpLongTargetBeforeFollowingAddress: pc]						ifFalse: [backEnd jumpLongConditionalTargetBeforeFollowingAddress: pc].		"Find target from jump.  A jump to the MNU entry-point should collect #doesNotUnderstand:"		(cPIC containsAddress: entryPoint)			ifTrue:				[value := objectMemory splObj: SelectorDoesNotUnderstand]			ifFalse:				[targetMethod := self cCoerceSimple: entryPoint - cmNoCheckEntryOffset to: #'CogMethod *'.				 self assert: targetMethod isCMMethodEtAl.				 value := targetMethod methodObject].		objectMemory storePointer: i * 2 ofObject: tuple withValue: value]! !!Cogit methodsFor: 'pic - helpers - api' stamp: 'NMS 2/27/2026 17:40'!extendPIC: aPIC withMethodsToPIC: aCollectionWithMethodsToPIC withTags: aCollectionWithTags andSelector: aPICSelector from: startingIndex to: lastIndex	<api>	<var: #aPIC type: #'CogMethod *'>	<var: #cogMethodToPIC type: #'CogMethod *'>	| addrOfMethodToPIC index tagOfMethodToPIC |	index := startingIndex.	[index < lastIndex] whileTrue: [		| cogMethodToPIC inlineCacheTagRepresentation |		addrOfMethodToPIC := objectMemory fetchPointer: index ofObject: aCollectionWithMethodsToPIC.		tagOfMethodToPIC := objectMemory fetchPointer: index ofObject: aCollectionWithTags.		cogMethodToPIC :=			(coInterpreter methodHasCogMethod: addrOfMethodToPIC)				ifTrue:  [ coInterpreter cogMethodOf: addrOfMethodToPIC ]				ifFalse: [ self cogit cog: addrOfMethodToPIC selector: aPICSelector ]. "If methodToPic not jitted -> JIT IT first"		"If It's not in the PIC -> ADD IT"		(self cPIC: aPIC HasTarget: cogMethodToPIC) ifFalse: [			inlineCacheTagRepresentation := objectRepresentation inlineCacheTagForClass: tagOfMethodToPIC.			self cogExtendPIC: aPIC				CaseNMethod: addrOfMethodToPIC				tag: inlineCacheTagRepresentation				isMNUCase: false.		].		index := index + 1.	].	backEnd		flushICacheFrom: aPIC asUnsignedInteger		to: aPIC asUnsignedInteger + closedPICSize.! !!Cogit methodsFor: 'pic - helpers - api' stamp: 'NMS 2/27/2026 17:37'!generatePICForMethods: anOopCollectionWithMethodsToPIC tags: anOopCollectionWithTags andSelector: aPICSelector	<api>	<returnTypeC: #'CogMethod *'>	| addrOfFirstElementToPIC addrOfSecondElementToPIC firstElementToPICJitted index lengthOfaCollectionWithMethodsToPIC pic tagOfSecondElementToPIC |	lengthOfaCollectionWithMethodsToPIC := objectMemory numSlotsOf: anOopCollectionWithMethodsToPIC.	" IF len(aCollectionWithMethodsToPIC) == 1 => Don't need to to anything, just an IC"	" IF len(aCollectionWithMethodsToPIC) == 2 => I create a Closed PIC"	" IF len(aCollectionWithMethodsToPIC) > 2 => I get into the look extending the PIC"	addrOfFirstElementToPIC := objectMemory fetchPointer: 0 ofObject: anOopCollectionWithMethodsToPIC.	(coInterpreter methodHasCogMethod: addrOfFirstElementToPIC) ifTrue: [		firstElementToPICJitted := coInterpreter cogMethodOf: addrOfFirstElementToPIC.	] ifFalse: [		firstElementToPICJitted := self cog: addrOfFirstElementToPIC selector: aPICSelector.	].	"if the length of aCollectionWithMethodsToPIC is 1 no need to create the PIC, IC is who takes the role here, just patch the method"	(lengthOfaCollectionWithMethodsToPIC >= 2) ifFalse: [		^ firstElementToPICJitted.	].	"if the length of aCollectionWithMethodsToPIC is at least 2, I need to create the PIC"	addrOfSecondElementToPIC := objectMemory fetchPointer: 1 ofObject: anOopCollectionWithMethodsToPIC.	"The tag of the first element is calculated automatically from the jitted method"	tagOfSecondElementToPIC := objectMemory fetchPointer: 1 ofObject: anOopCollectionWithTags.	self ensureWritableCodeZone.	 "If addrOfSecondElementToPIC not jitted -> JIT IT first"	(coInterpreter methodHasCogMethod: addrOfSecondElementToPIC) ifFalse: [		self cogit cog: addrOfSecondElementToPIC selector: aPICSelector	].	pic := self			cogPICSelector: aPICSelector			numArgs: (firstElementToPICJitted cmNumArgs)			Case0Method: firstElementToPICJitted			Case1Method: addrOfSecondElementToPIC			tag: (objectRepresentation inlineCacheTagForClass: tagOfSecondElementToPIC)			isMNUCase: false.	"We don't at this point exactly which are the error codes"	(pic asInteger between: -1024 and: -1) ifTrue:[		^nil	].	"if the length of aCollectionWithMethodsToPIC is bigger than 2, i need now to extend the PIC"	backEnd		flushICacheFrom: pic asUnsignedInteger		to: pic asUnsignedInteger + closedPICSize.	index := 2.	self		extendPIC: pic		withMethodsToPIC: anOopCollectionWithMethodsToPIC		withTags: anOopCollectionWithTags		andSelector: aPICSelector		from: index		to: lengthOfaCollectionWithMethodsToPIC.	^pic.! !!Cogit methodsFor: 'pic - helpers - api' stamp: 'NMS 10/14/2025 15:02'!getAPICToExtendFor: cogMethod withSelector: aPICSelector atSendReturnPCs: anOopCollectionWithSendReturnPCs	<api>	<var: #cogMethod type: #'CogMethod *'>	<var: #anOopCollectionWithSendReturnPCs type: #sqInt>	<returnTypeC: #'CogMethod *'>	| args pic |	cogMethod isCMMethodEtAl ifFalse: [		^nil	].	args := objectMemory instantiateClass: (objectMemory splObj: ClassArray) indexableSize: 3.	objectMemory storePointer: 0 ofObject: args withValue: (self cCoerceSimple: (cogMethod asInteger) to: #'sqInt').	objectMemory storePointer: 1 ofObject: args withValue: aPICSelector.	objectMemory storePointer: 2 ofObject: args withValue: anOopCollectionWithSendReturnPCs.	pic := self		mapFor: cogMethod		performUntil: (#getAPICToExtendWith:Mcpc:args:)		arg: args asVoidPointer.	(pic = 0) ifTrue: [		^ nil.	].	^self cCoerceSimple: pic to: #'CogMethod *'! !!Cogit methodsFor: 'pic - helpers - api' stamp: 'NMS 2/27/2026 23:09'!getJITAndPICUsedSpace	<api>	| result jitSpace jitAmount closedPICSpace closedPICAmount openPICSpace openPICAmount end m |	result := objectMemory instantiateClass: (objectMemory splObj: ClassArray) indexableSize: 6.	result ifNil: [^-1].		jitSpace := 0.	jitAmount := 0.	closedPICSpace := 0.	closedPICAmount := 0.	openPICSpace := 0.	openPICAmount := 0.	m := self cogit methodZoneBase.	end := self cogit methodZone freeStart.	[ m < end ] whileTrue: [		| cogMethod blockSize |		cogMethod := self cCoerceSimple: m to: #'CogMethod *'.				blockSize := cogMethod blockSize.		" cmType := cogMethod cmType . cmType >= 5 "		(cogMethod isCMMethodEtAl) ifTrue: [			jitSpace := jitSpace + blockSize.			jitAmount := jitAmount + 1.		].		"cmType = 2"		(cogMethod isCMClosedPIC) ifTrue: [			closedPICSpace := closedPICSpace + blockSize.			closedPICAmount := closedPICAmount + 1.		].		"cmType = 3"		(cogMethod isCMOpenPIC) ifTrue: [			openPICSpace := openPICSpace + blockSize.			openPICAmount := openPICAmount + 1.		].		m := m + blockSize	].	objectMemory		storePointer: 0		ofObject: result		withValue: (objectMemory integerObjectOf: jitSpace).	objectMemory		storePointer: 1		ofObject: result		withValue: (objectMemory integerObjectOf: jitAmount).			objectMemory		storePointer: 2		ofObject: result		withValue: (objectMemory in